using FluentValidation; using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.UpdateUserStatus;
public sealed record UpdateUserStatusCommand(Guid Id,bool IsActive):IRequest<UpdateUserStatusResponse>;
public sealed record UpdateUserStatusResponse(Guid Id,bool IsActive);
public sealed class UpdateUserStatusValidator:AbstractValidator<UpdateUserStatusCommand>{public UpdateUserStatusValidator()=>RuleFor(x=>x.Id).NotEmpty();}
public sealed class UpdateUserStatusHandler(IApplicationDbContext db,ICurrentUserService actor,IClock clock):IRequestHandler<UpdateUserStatusCommand,UpdateUserStatusResponse>{public async Task<UpdateUserStatusResponse> Handle(UpdateUserStatusCommand r,CancellationToken ct){var u=db.Users.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("User was not found.");var old=u.IsActive;u.SetStatus(r.IsActive);if(!r.IsActive)foreach(var token in db.RefreshTokens.Where(x=>x.UserId==u.Id&&x.RevokedAt==null).ToArray())token.Revoke(clock.UtcNow,"user-deactivated");SecurityAuditWriter.Add(db,actor.UserId,"UserStatusChanged","User",u.Id.ToString(),old.ToString(),r.IsActive.ToString());await db.SaveChangesAsync(ct);return new(u.Id,u.IsActive);}}
public static class UpdateUserStatusEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapPut("/users/{id:guid}/status",async(Guid id,UpdateUserStatusCommand c,ISender s,CancellationToken t)=>Results.Ok(await s.Send(c with{Id=id},t))).RequirePermission("Admin.Users.Manage",Capability.Full);}
